#include <bits/stdc++.h>
using namespace std;
#define MAXNODES 15000
struct Edge {
    int to, capacity, flow, cost;
};
vector<Edge> edge_list;
vector<int> adjacency[MAXNODES];
long long total_cost, dist[MAXNODES];
int n, m, k, c, d, parent[MAXNODES], parent_edge[MAXNODES], inq[MAXNODES], s=9998, t=9999, cur, i, j;
void addEdge(int u, int v, int cap, int cst) {
    adjacency[u].push_back(edge_list.size()); edge_list.push_back({v, cap, 0, cst});
    adjacency[v].push_back(edge_list.size()); edge_list.push_back({u, 0, 0, -cst});
}
void augmentFlow() {
    fill(dist, dist + 10000, (long long)1e18);
    fill(parent, parent + 10000, -1);
    fill(parent_edge, parent_edge + 10000, -1);
    fill(inq, inq + 10000, 0);
    dist[s] = 0;
    queue<int> q;
    q.push(s);
    inq[s] = 1;
    cur = t;
    while (!q.empty()) {
        int u = q.front(); q.pop();
        inq[u] = 0;
        for (auto e_idx : adjacency[u]) {
            if (edge_list[e_idx].capacity - edge_list[e_idx].flow == 0) continue;
            int cst = edge_list[e_idx].cost, y = edge_list[e_idx].to;
            if (dist[y] > dist[u] + cst) {
                dist[y] = dist[u] + cst;
                parent[y] = u;
                parent_edge[y] = e_idx;
                if (!inq[y]) { inq[y] = 1; q.push(y); }
            }
        }
    }
    int node = cur;
    while (node != s) {
        edge_list[parent_edge[node]].flow++;
        edge_list[parent_edge[node] ^ 1].flow--;
        node = parent[node];
    }
    total_cost += dist[t];
}
int main() {
    cin >> n >> m >> k >> c >> d;
    int x, y;
    for (int i = 1; i <= k; i++) { cin >> x; x--; addEdge(s, x, 1, 0); }
    for (int i = 1; i <= 101; i++) addEdge((i - 1) * n, t, k, (i - 1) * c);
    for (int i = 1; i <= m; i++) {
        cin >> x >> y; x--; y--;
        for (int i = 1; i <= 100; i++) {
            for (int j = 1; j <= k; j++) {
                addEdge(x + (i - 1) * n, y + (i - 1) * n + n, 1, d * ((j - 1) * 2 + 1));
                addEdge(y + (i - 1) * n, x + (i - 1) * n + n, 1, d * ((j - 1) * 2 + 1));
            }
        }
    }
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= 100; j++) {
            addEdge(i - 1 + (j - 1) * n, i - 1 + (j - 1) * n + n, k, 0);
        }
    }
    for (int i = 1; i <= k; i++) augmentFlow();
    cout << total_cost << endl;
    return 0;
}
